   values([r.selected.radius,r.selected.vc,r.full.escape,r.cut.escape,r.velocity,r.energyScaled]);const name=select.value==='cut'?'截断模型':'延伸NFW',label=e=>Math.abs(e)<=1e-12*r.halo.V**2?'临界零能':e<0?'束缚能量':'非束缚能量',ef=.5*r.velocity**2+r.full.phi,ec=.5*r.velocity**2+r.cut.phi;
