   status('锐截断只用于隔离外层质量的势贡献；它不代表真实暗晕的物理硬边缘，也不保证对应稳定的分布函数。','reference');host.dataset.energy=r.energyScaled;host.dataset.fullEscape=r.full.escape;host.dataset.cutEscape=r.cut.escape;host.dataset.circle=r.selected.vc;
